head.script:
scwin.test = function(row, col, text) {
    return row + "," + col + "," + text;
}
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.Dbclick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 2. 브라우저에서 textImage 컬럼의 셀들을 더블클릭한다.
    //2. In the browser, double-click the cells in the textImage column.
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick($p.id+'wq_uuid_3_cell_0_0')");
    WebSquare.wUnit.addCommand("pause", "1000");
    // verify step 2. 더블클릭한 셀에 포커스가 된다.(그전버전에서는 포커스가 될 시 이미지가 사라지는 현상이 발생했음.)
    //2. Double-click to focus on the cell.(In the previous version, when the image was focused, the image disappeared.)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#G_wq_uuid_3__col1').css('width') <= '170px'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.g = [];
    for (var i = 0; i < 3 * 100; i++) {
        g.push(i);
    }
    dataList1.setData(g);
    //Function unitTest
    //Created By: Sang.do
    //Created By: 19-Mar-2018
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
